+    <Flex direction="column" gap="5">
+      <Card space="5">
+        <Flex direction="column" gap="4">
+          <Text variant="header-3">Новая задача</Text>
+          <Flex gap="3" wrap>
+            <Flex grow>
+              <TextInput
+                value={title}
+                onUpdate={setTitle}
+                placeholder="Что нужно сделать?"
+                size="l"
+              />
+            </Flex>
+            <Button view="action" size="l" onClick={addTask}>
+              Добавить
+            </Button>
+          </Flex>
+        </Flex>
+      </Card>
+
+      <Flex direction="column" gap="3">
+        {tasks.map((task) => (
+          <Card key={task.id} space="4">
+            <Flex gap="4" alignItems="center" justifyContent="space-between" wrap>
+              <Text>{task.title}</Text>
+              <Switch
+                checked={task.status === "done"}
+                onUpdate={(checked) => toggleTask(task.id)}
+              />
+            </Flex>
+          </Card>
+        ))}
+      </Flex>
+    </Flex>
+  );
+}
+
+function SettingsPage({
+  theme,
+  onChangeTheme,
+}: {
+  theme: Theme;
+  onChangeTheme: (theme: Theme) => void;
+}) {
+  return (
+    <Flex direction="column" gap="5">
+      <Card space="5">
+        <Flex direction="column" gap="3">
+          <Text variant="header-3">Оформление</Text>
+          <Text color="secondary">
+            Выбор сохраняется в браузере и применяется ко всему приложению.
+          </Text>
+          <SegmentedRadioGroup<Theme>
+            value={theme}
+            onUpdate={(nextTheme) => onChangeTheme(nextTheme)}
+            aria-label="Тема оформления"
+          >
+            <SegmentedRadioGroup.Option value="light" content="Светлая" />
+            <SegmentedRadioGroup.Option value="dark" content="Тёмная" />
+          </SegmentedRadioGroup>
+        </Flex>
+      </Card>
+
+      <Card space="5">
+        <Flex direction="column" gap="3">
+          <Text variant="header-3">Рабочее время</Text>
+          <Flex gap="3" wrap>
+            <Flex grow>
+              <TextInput defaultValue="09:30" label="Начало" size="l" />
+            </Flex>
+            <Flex grow>
+              <TextInput defaultValue="18:00" label="Конец" size="l" />
+            </Flex>
+          </Flex>
+        </Flex>
+      </Card>
+    </Flex>
+  );
+}
